   433  PJ *
   434  pj_init_ctx(projCtx ctx, int argc, char **argv) {
   435      char *s, *name;
   436      paralist *start = NULL;
   437      PJ *(*proj)(PJ *);
   438      paralist *curr;
   439      int i;
   440      int found_def = 0;
   441      PJ *PIN = 0;
   442
   443      if (0==ctx)
   444          ctx = pj_get_default_ctx ();
   445
   446      ctx->last_errno = 0;
   447      start = NULL;
   448
   449      if (argc <= 0) {
   450          pj_ctx_set_errno (ctx, PJD_ERR_NO_ARGS);
   451          return 0;
   452      }
   453
   454      /* put arguments into internal linked list */
   455      start = curr = pj_mkparam(argv[0]);
   456
   457      /* build parameter list and expand +init's. Does not take care of a single +init. */
   458      for (i = 1; i < argc; ++i) {
   459          curr->next = pj_mkparam(argv[i]);
   460
   461          /* check if +init present */
   462          if (pj_param(ctx, curr, "tinit").i) {
   463              found_def = 0;
   464              curr = get_init(ctx, &curr, curr->next, pj_param(ctx, curr, "sinit").s, &found_def);
   465              if (!curr)
   466                  return pj_dealloc_params (ctx, start, PJD_ERR_NO_ARGS);
   467
   468              if (!found_def)
   469                  return pj_dealloc_params (ctx, start, PJD_ERR_NO_OPTION_IN_INIT_FILE);
   470
   471          } else {
   472              curr = curr->next;
   473          }
   474      }
   475
   476      /* in case the parameter list only consist of a +init parameter
   477         it is expanded here (will not be handled in the above loop). */
   478      if (pj_param(ctx, start, "tinit").i && argc == 1) {
   479          found_def = 0;
   480          curr = get_init(ctx, &start, curr, pj_param(ctx, start, "sinit").s, &found_def);
   481          if (!curr)
   482              return pj_dealloc_params (ctx, start, PJD_ERR_NO_ARGS);
   483          if (!found_def)
   484              return pj_dealloc_params (ctx, start, PJD_ERR_NO_OPTION_IN_INIT_FILE);
   485      }
   486
   487      if (ctx->last_errno)
   488          return pj_dealloc_params (ctx, start, ctx->last_errno);
   489
   490      /* find projection selection */
   491      if (!(name = pj_param(ctx, start, "sproj").s))
   492          return pj_default_destructor (PIN, PJD_ERR_PROJ_NOT_NAMED);
   493      for (i = 0; (s = pj_list[i].id) && strcmp(name, s) ; ++i) ;
   494
   495      if (!s)
   496          return pj_dealloc_params (ctx, start, PJD_ERR_UNKNOWN_PROJECTION_ID);
   497
   498      /* set defaults, unless inhibited */
   499      if (!(pj_param(ctx, start, "bno_defs").i))
   500          curr = get_defaults(ctx,&start, curr, name);
   501      proj = (PJ *(*)(PJ *)) pj_list[i].proj;
   502
   503      /* allocate projection structure */
   504      PIN = proj(0);
   505      if (0==PIN)
   506          return pj_dealloc_params (ctx, start, ENOMEM);
   507
   508      PIN->ctx = ctx;
   509      PIN->params = start;
   510      PIN->is_latlong = 0;
   511      PIN->is_geocent = 0;
   512      PIN->is_long_wrap_set = 0;
   513      PIN->long_wrap_center = 0.0;
   514      strcpy( PIN->axis, "enu" );
   515
   516      PIN->gridlist = NULL;
   517      PIN->gridlist_count = 0;
   518
   519      PIN->vgridlist_geoid = NULL;
   520      PIN->vgridlist_geoid_count = 0;
   521
   522      /* set datum parameters */
   523      if (pj_datum_set(ctx, start, PIN))
   524          return pj_default_destructor (PIN, PJD_ERR_MISSING_ARGS);
   525
   526      /* set ellipsoid/sphere parameters */
   527      if (pj_ell_set(ctx, start, &PIN->a, &PIN->es)) {
   528          pj_log (ctx, PJ_LOG_DEBUG_MINOR, "pj_init_ctx: Must specify ellipsoid or sphere");
   529          return pj_default_destructor (PIN, PJD_ERR_MISSING_ARGS);
   530      }
   531
   532      PIN->a_orig = PIN->a;
   533      PIN->es_orig = PIN->es;
   534
   535      /* Compute some ancillary ellipsoidal parameters */
   536      PIN->e = sqrt(PIN->es);      /* eccentricity */
   537      PIN->alpha = asin (PIN->e);  /* angular eccentricity */
   538
   539      /* second eccentricity */
   540      PIN->e2  = tan (PIN->alpha);
   541      PIN->e2s = PIN->e2 * PIN->e2;
   542
   543      /* third eccentricity */
   544      PIN->e3    = (0!=PIN->alpha)? sin (PIN->alpha) / sqrt(2 - sin (PIN->alpha)*sin (PIN->alpha)): 0;
   545      PIN->e3s = PIN->e3 * PIN->e3;
   546
   547      /* flattening */
   548      PIN->f  = 1 - cos (PIN->alpha);   /* = 1 - sqrt (1 - PIN->es); */
   549      PIN->rf = PIN->f != 0.0 ? 1.0/PIN->f: HUGE_VAL;
   550
   551      /* second flattening */
   552      PIN->f2  = (cos(PIN->alpha)!=0)? 1/cos (PIN->alpha) - 1: 0;
   553      PIN->rf2 = PIN->f2 != 0.0 ? 1/PIN->f2: HUGE_VAL;
   554
   555      /* third flattening */
   556      PIN->n  = pow (tan (PIN->alpha/2), 2);
   557      PIN->rn = PIN->n != 0.0 ? 1/PIN->n: HUGE_VAL;
   558
   559      /* ...and a few more */
   560      PIN->b  = (1 - PIN->f)*PIN->a;
   561      PIN->rb = 1. / PIN->b;
   562      PIN->ra = 1. / PIN->a;
   563
   564      PIN->one_es = 1. - PIN->es;
   565      if (PIN->one_es == 0.)
   566          return pj_default_destructor (PIN, PJD_ERR_ECCENTRICITY_IS_ONE);
   567      PIN->rone_es = 1./PIN->one_es;
   568
   569
   570
   571      /* Now that we have ellipse information check for WGS84 datum */
   572      if( PIN->datum_type == PJD_3PARAM
   573          && PIN->datum_params[0] == 0.0
   574          && PIN->datum_params[1] == 0.0
   575          && PIN->datum_params[2] == 0.0
   576          && PIN->a == 6378137.0
   577          && ABS(PIN->es - 0.006694379990) < 0.000000000050 )/*WGS84/GRS80*/
   578      {
   579          PIN->datum_type = PJD_WGS84;
   580      }
   581
   582      /* set PIN->geoc coordinate system */
   583      PIN->geoc = (PIN->es != 0.0 && pj_param(ctx, start, "bgeoc").i);
   584
   585      /* over-ranging flag */
   586      PIN->over = pj_param(ctx, start, "bover").i;
   587
   588      /* vertical datum geoid grids */
   589      PIN->has_geoid_vgrids = pj_param(ctx, start, "tgeoidgrids").i;
   590      if( PIN->has_geoid_vgrids ) /* we need to mark it as used. */
   591          pj_param(ctx, start, "sgeoidgrids");
   592
   593      /* longitude center for wrapping */
   594      PIN->is_long_wrap_set = pj_param(ctx, start, "tlon_wrap").i;
   595      if (PIN->is_long_wrap_set) {
   596          PIN->long_wrap_center = pj_param(ctx, start, "rlon_wrap").f;
   597          /* Don't accept excessive values otherwise we might perform badly */
   598          /* when correcting longitudes around it */
   599          /* The test is written this way to error on long_wrap_center "=" NaN */
   600          if( !(fabs(PIN->long_wrap_center) < 10 * M_TWOPI) )
   601              return pj_default_destructor (PIN, PJD_ERR_LAT_OR_LON_EXCEED_LIMIT);
   602      }
   603
   604      /* axis orientation */
   605      if( (pj_param(ctx, start,"saxis").s) != NULL )
   606      {
   607          static const char *axis_legal = "ewnsud";
   608          const char *axis_arg = pj_param(ctx, start,"saxis").s;
   609          if( strlen(axis_arg) != 3 )
   610              return pj_default_destructor (PIN, PJD_ERR_AXIS);
   611
   612          if( strchr( axis_legal, axis_arg[0] ) == NULL
   613              || strchr( axis_legal, axis_arg[1] ) == NULL
   614              || strchr( axis_legal, axis_arg[2] ) == NULL)
   615              return pj_default_destructor (PIN, PJD_ERR_AXIS);
   616
   617          /* it would be nice to validate we don't have on axis repeated */
   618          strcpy( PIN->axis, axis_arg );
   619      }
