    38  /* allocate and deallocate memory */
    39  /* These routines are used so that applications can readily replace
    40  ** projection system memory allocation/deallocation call with custom
    41  ** application procedures.  */
    42
    43  #include "projects.h"
    44  #include <errno.h>
