   109  void *pj_dealloc (void *ptr) {
   110  /***********************************************************************
   111  pj_dealloc supports the common use case of "clean up and return a null
   112  pointer" to signal an error in a multi level allocation:
   113
   114      struct foo { int bar; int *baz; };
   115
   116      struct foo *p = pj_calloc (1, sizeof (struct foo));
   117      if (0==p)
   118          return 0;
   119
   120      p->baz = pj_calloc (10, sizeof(int));
